int main(int argc,char**argv)try{if(argc!=3)throw std::invalid_argument("Usage: humanoid-native-pose-quality ASSET_DIRECTORY OUTPUT_DIRECTORY");const std::filesystem::path out=argv[2];std::filesystem::create_directories(out);Json report{{"scope","Descriptive pose comparison to complete original artist skin/node/IBM reference after all native solvers finish. Exact source identities, common physical pivots/world axes, all native vertices/secondary influences included. Artist similarity is not universal visual acceptance."},{"assets",Json::array()}};for(auto*sex:{"female","male"}){report["assets"].push_back(pq::measure(std::filesystem::path(argv[1])/"vroid"/(std::string("base-")+sex+".vrm"),out/sex));std::ofstream(out/"quality.json")<<report.dump(2)<<'\n';}std::cout<<"PASS independent full artist rest/pose reference and actual native deformation measured for both complete assets\n";return 0;}catch(const std::exception&e){std::cerr<<"FAIL "<<e.what()<<'\n';return 1;}
